/* ===================================================================== */

const $ = s => document.querySelector(s);
const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;

/* ---------- Text ---------- */
$("#his-name").innerHTML = [...CONFIG.hisName].map(c => c === " " ? " " : `<span>${c}</span>`).join("");
$("#his-name").querySelectorAll("span").forEach((s,i)=>s.style.animationDelay = (i*0.12)+"s");
$("#lead").textContent = CONFIG.lead;
const bd = new Date(CONFIG.birthday + "T00:00:00");
$("#bday-date").textContent = `${bd.getDate()} tháng ${bd.getMonth()+1}, ${bd.getFullYear()}`;
function countUp(el, to){ if(reduce){el.textContent=to;return}
  const t0=performance.now(); const step=t=>{const k=Math.min(1,(t-t0)/1400); el.textContent=Math.round(to*(1-Math.pow(1-k,3))).toLocaleString("vi-VN"); if(k<1) requestAnimationFrame(step)}; requestAnimationFrame(step); }
const days = Math.max(0, Math.floor((Date.now() - new Date(CONFIG.togetherSince+"T00:00:00")) / 864e5));
$("#days").textContent = days.toLocaleString("vi-VN"); $("#trips").textContent = CONFIG.memories.length; $("#age").textContent = bd.getFullYear()-CONFIG.bornYear;
countUp($("#days"), days); countUp($("#trips"), CONFIG.memories.length); countUp($("#age"), bd.getFullYear()-CONFIG.bornYear);

/* ---------- Love timer ---------- */
const since = new Date(CONFIG.togetherSince+"T00:00:00");
function loveTick(){ let d=Math.max(0,(Date.now()-since)/1000); const D=Math.floor(d/86400); d-=D*86400; const H=Math.floor(d/3600); d-=H*3600; const M=Math.floor(d/60); const S=Math.floor(d-M*60);
  $("#love-timer").innerHTML=`Mình đã thương nhau <b>${D.toLocaleString("vi-VN")}</b> ngày <b>${H}</b> giờ <b>${M}</b> phút <b>${String(S).padStart(2,"0")}</b> giây`; }
loveTick(); setInterval(loveTick,1000);
$("#quote").textContent = CONFIG.quote; $("#forever").textContent = CONFIG.forever;

/* ---------- Reasons ---------- */
const heartSvg = `<svg viewBox="0 0 24 24"><path fill="currentColor" d="M12 21s-7.5-4.6-9.6-9.2C.9 8.4 3 4.5 6.7 4.5c2.1 0 3.6 1.2 4.3 2.6.7-1.4 2.2-2.6 4.3-2.6 3.7 0 5.8 3.9 4.3 7.3C19.5 16.4 12 21 12 21z"/></svg>`;
CONFIG.reasons.forEach((t,i)=>{ const b=document.createElement("button"); b.type="button"; b.className="flip"; b.setAttribute("aria-label","Lật thẻ");
  b.innerHTML=`<div class="in"><div class="f">${heartSvg}<span>Điều thứ ${i+1}</span></div><div class="b"></div></div>`;
  b.querySelector(".b").textContent=t;
  b.addEventListener("click",()=>{ b.classList.toggle("open"); if(b.classList.contains("open")) burst(b.getBoundingClientRect(),14,"heart"); });
  setTimeout(()=>document.getElementById("reason-grid").appendChild(b),0); });

